def compute(vars):
    us_owned = vars["v1"]
    total_owned = vars["v2"]
    if total_owned == 0:
        return None
    ratio = us_owned / total_owned
    value = ratio * 100
    return {
        "value": value,
        "trace": {
            "us_owned": us_owned,
            "total_owned": total_owned,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
